answer:
function throttle<F extends (...args:any[])=>any>(fn: F, ms: number): F {
  let last = 0; let lastResult: ReturnType<F>;
  return function(this:any, ...a:Parameters<F>) {
    const now = Date.now();
    if (now - last >= ms) { last = now; lastResult = fn.apply(this, a); }
    return lastResult as ReturnType<F>;
  } as F;
}
